From aff722b584172d71e8ba20c2844ec769cd78295b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:07:42 +0100
Subject: [PATCH] applets/systemtray: map XEmbed icon clicks with the Xwayland
 scale

Clicks on XEmbed tray icons were scaled by the panel's pixel ratio and
the screen's position, but Xwayland uses KWin's own scale everywhere, so
the click missed the icon. Read that scale from kwinrc and apply it.

BUG: 491582
---
 applets/systemtray/systemtray.cpp | 35 ++++++++++++++++---------------
 applets/systemtray/systemtray.h   |  4 +++-
 2 files changed, 21 insertions(+), 18 deletions(-)

diff --git a/applets/systemtray/systemtray.cpp b/applets/systemtray/systemtray.cpp
index 4c1db7a2e7..fad4d3c4e0 100644
--- a/applets/systemtray/systemtray.cpp
+++ b/applets/systemtray/systemtray.cpp
@@ -17,7 +17,6 @@
 #include "systemtraymodel.h"
 #include "systemtraysettings.h"

-#include <QGuiApplication>
 #include <QMenu>
 #include <QMetaMethod>
 #include <QMetaObject>
@@ -26,7 +25,6 @@
 #include <QQuickWindow>
 #include <QScreen>
 #include <QTimer>
-#include <qpa/qplatformscreen.h>

 #include <Plasma/Applet>
 #include <Plasma/Corona>
@@ -136,16 +134,27 @@ void SystemTray::init()
     });

     if (KWindowSystem::isPlatformWayland()) {
-        auto config = KSharedConfig::openConfig(QStringLiteral("kdeglobals"), KConfig::NoGlobals);
-        KConfigGroup kscreenGroup = config->group(QStringLiteral("KScreen"));
+        auto kdeglobalsConfig = KSharedConfig::openConfig(QStringLiteral("kdeglobals"), KConfig::NoGlobals);
+        KConfigGroup kscreenGroup = kdeglobalsConfig->group(QStringLiteral("KScreen"));
         m_xwaylandClientsScale = kscreenGroup.readEntry("XwaylandClientsScale", true);

-        m_configWatcher = KConfigWatcher::create(config);
-        connect(m_configWatcher.data(), &KConfigWatcher::configChanged, this, [this](const KConfigGroup &group, const QByteArrayList &names) {
+        m_kdeglobalsConfigWatcher = KConfigWatcher::create(kdeglobalsConfig);
+        connect(m_kdeglobalsConfigWatcher.data(), &KConfigWatcher::configChanged, this, [this](const KConfigGroup &group, const QByteArrayList &names) {
             if (group.name() == u"KScreen" && names.contains(QByteArrayLiteral("XwaylandClientsScale"))) {
                 m_xwaylandClientsScale = group.readEntry("XwaylandClientsScale", true);
             }
         });
+
+        auto kwinrcConfig = KSharedConfig::openConfig(QStringLiteral("kwinrc"), KConfig::NoGlobals);
+        KConfigGroup xwaylandGroup = kwinrcConfig->group(QStringLiteral("Xwayland"));
+        m_xwaylandScaleFactor = xwaylandGroup.readEntry("Scale", 1.0);
+
+        m_kwinrcConfigWatcher = KConfigWatcher::create(kwinrcConfig);
+        connect(m_kwinrcConfigWatcher.data(), &KConfigWatcher::configChanged, this, [this](const KConfigGroup &group, const QByteArrayList &names) {
+            if (group.name() == u"Xwayland" && names.contains(QByteArrayLiteral("Scale"))) {
+                m_xwaylandScaleFactor = group.readEntry("Scale", 1.0);
+            }
+        });
     }
 }

@@ -338,17 +347,9 @@ QPointF SystemTray::popupPosition(QQuickItem *visualParent, int x, int y)
                 return pos;
             }

-            const qreal devicePixelRatio = window->devicePixelRatio();
-
-            if (QGuiApplication::screens().size() == 1) {
-                return pos * devicePixelRatio;
-            }
-
-            const QRect geometry = window->screen()->geometry();
-            const QRect nativeGeometry = window->screen()->handle()->geometry();
-            const QPointF nativeGlobalPosOnCurrentScreen = (pos - geometry.topLeft()) * devicePixelRatio;
-
-            return nativeGeometry.topLeft() + nativeGlobalPosOnCurrentScreen;
+            // KWin scales the whole Xwayland coordinate space by its own Xwayland scale,
+            // which is not necessarily the scale of the screen the tray is on
+            return pos * m_xwaylandScaleFactor;
         }
     }

diff --git a/applets/systemtray/systemtray.h b/applets/systemtray/systemtray.h
index 8f06cfadf6..239199d08f 100644
--- a/applets/systemtray/systemtray.h
+++ b/applets/systemtray/systemtray.h
@@ -91,8 +91,10 @@ private:
     void initSettingsAndRegistry();
     void initRegistry();

-    KConfigWatcher::Ptr m_configWatcher;
+    KConfigWatcher::Ptr m_kdeglobalsConfigWatcher;
+    KConfigWatcher::Ptr m_kwinrcConfigWatcher;
     bool m_xwaylandClientsScale = true;
+    double m_xwaylandScaleFactor = 1.0;

     SystemTraySettings *m_settings = nullptr;
     PlasmoidRegistry *m_plasmoidRegistry = nullptr;
-- 
